// Monitor: Notifications Verification
bthread("monitor:Notifications", function () {
  while (true) {
    let e = bp.sync({ waitFor: matchAnyNotificationsAdded() });
    let NotificationRequest = (e.data.parameters && e.data.parameters["NotificationRequest"]) ? e.data.parameters["NotificationRequest"] : e.data["NotificationRequest"];
    let PatchedNotificationRequest = (e.data.parameters && e.data.parameters["PatchedNotificationRequest"]) ? e.data.parameters["PatchedNotificationRequest"] : e.data["PatchedNotificationRequest"];
    let event_type = (e.data.parameters && e.data.parameters["event_type"]) ? e.data.parameters["event_type"] : e.data["event_type"];
    let id = (e.data.parameters && e.data.parameters["id"]) ? e.data.parameters["id"] : e.data["id"];
    let limit = (e.data.parameters && e.data.parameters["limit"]) ? e.data.parameters["limit"] : e.data["limit"];
    let object_id = (e.data.parameters && e.data.parameters["object_id"]) ? e.data.parameters["object_id"] : e.data["object_id"];
    let object_type = (e.data.parameters && e.data.parameters["object_type"]) ? e.data.parameters["object_type"] : e.data["object_type"];
    let offset = (e.data.parameters && e.data.parameters["offset"]) ? e.data.parameters["offset"] : e.data["offset"];
    let ordering = (e.data.parameters && e.data.parameters["ordering"]) ? e.data.parameters["ordering"] : e.data["ordering"];
    let user = (e.data.parameters && e.data.parameters["user"]) ? e.data.parameters["user"] : e.data["user"];
    // Block Deletion while Verifying Existence
    block(matchDeletedNotifications(NotificationRequest, PatchedNotificationRequest, event_type, id, limit, object_id, object_type, offset, ordering, user), function() {
      bp.log.info(`Monitor Notifications: Verifying persistence of ID ${id} inside deletion block.`);
        verifyNotificationsExists(NotificationRequest, PatchedNotificationRequest, event_type, id, limit, object_id, object_type, offset, ordering, user);
    });
  }
});

